const cats=['ภาพรวมของห้อง','ห้องนอน','ห้องน้ำ','ห้องครัว','เฟอร์นิเจอร์และเครื่องใช้ไฟฟ้า','สภาพห้องก่อนผู้เช่าเข้า','สภาพห้องหลังผู้เช่าย้ายออก','รูปความเสียหายและการซ่อมแซม'],defaults=[['vacant','ว่าง','#94a3b8'],['occupied','มีผู้เช่า','#10a57a'],['pending','รอผู้เช่าเข้า','#3b82f6'],['expiring','ใกล้หมดสัญญา','#f59e0b'],['repair','กำลังซ่อมแซม','#ef4444'],['renovation','ปิดปรับปรุง','#7c3aed']];
const dbp=new Promise((ok,no)=>{const r=indexedDB.open('condo-ledger',4);r.onupgradeneeded=()=>['properties','tenants','leases','contractVersions','photos','statuses','statusHistory','attachments','settings'].forEach(s=>{if(!r.result.objectStoreNames.contains(s))r.result.createObjectStore(s,{keyPath:'id'})});r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)});
