function page(n){$$('.page').forEach(x=>x.classList.toggle('visible',x.id===n));$$('nav button').forEach(x=>x.classList.toggle('active',x.dataset.page===n));$('#crumb').textContent=$(`nav button[data-page="${n}"]`).textContent;$('#title').textContent=$('#crumb').textContent.trim();$('aside').classList.remove('open')}
