function renderArchive(){const q=$('#leaseSearch').value?.toLowerCase()||'',pid=$('#leasePropertyFilter').value;$('#leasePropertyFilter').innerHTML='<option value="">ทุกห้อง</option>'+propOpts(false);if(pid)$('#leasePropertyFilter').value=pid;const ls=S.leases.filter(l=>(!pid||l.propertyId===pid)&&(`${l.tenantName} ${l.startDate} ${l.endDate}`).toLowerCase().includes(q)).sort((a,b)=>(b.startDate||'').localeCompare(a.startDate||''));$('#leaseTimeline').innerHTML=ls.map(l=>`<article class="lease-card"><span class="right badge">${esc(l.status)}</span><h3>${esc(S.properties.find(p=>p.id===l.propertyId)?.name||'ห้องที่ลบแล้ว')} · ${esc(l.tenantName||'ไม่ระบุผู้เช่า')}</h3><p>${l.startDate||'—'} ถึง ${l.endDate||'—'} · ${fmt(l.rent)}</p><p>เงินประกัน ${fmt(l.deposit)} · ${l.moveInDate?'เข้าอยู่ '+l.moveInDate:''}</p><button class="text" data-lease="${l.id}">แก้ไข</button></article>`).join('')||'<div class="panel empty">ยังไม่มีสัญญา</div>';$$('[data-lease]').forEach(b=>b.onclick=()=>leaseForm(S.leases.find(x=>x.id===b.dataset.lease)))}
