function leaseForm(l={}){modal(l.id?'แก้ไขสัญญา':'เพิ่มสัญญา',`<div class="form-grid"><label class="field">ห้อง *<select required name="propertyId">${S.properties.map(p=>`<option value="${p.id}" ${p.id===l.propertyId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label class="field">ชื่อผู้เช่า *<input required name="tenantName" value="${esc(l.tenantName)}"></label><label class="field">เริ่มสัญญา *<input type="date" required name="startDate" value="${l.startDate||iso()}"></label><label class="field">สิ้นสุดสัญญา *<input type="date" required name="endDate" value="${l.endDate||''}"></label><label class="field">ค่าเช่ารายเดือน<input type="number" min="0" name="rent" value="${l.rent||0}"></label><label class="field">เงินประกัน<input type="number" min="0" name="deposit" value="${l.deposit||0}"></label><label class="field">วันที่เข้าอยู่<input type="date" name="moveInDate" value="${l.moveInDate||''}"></label><label class="field">สถานะ<select name="status">${['Draft','Signed','Active','Expired','Terminated'].map(x=>`<option ${x===l.status?'selected':''}>${x}</option>`).join('')}</select></label><label class="field full">หมายเหตุ<textarea name="note">${esc(l.note)}</textarea></label></div>`,async d=>{if(d.endDate<d.startDate)throw Error('วันที่สิ้นสุดต้องไม่ก่อนวันเริ่ม');const overlap=S.leases.some(x=>x.id!==l.id&&x.propertyId===d.propertyId&&x.status!=='Terminated'&&x.startDate<=d.endDate&&x.endDate>=d.startDate);if(overlap)throw Error('ช่วงสัญญาทับซ้อนกับสัญญาเดิม กรุณาตรวจสอบ');let x={...l,...d,id:l.id||uid(),rent:+d.rent||0,deposit:+d.deposit||0,updatedAt:Date.now()};await put('leases',x);if(d.status==='Active'){let p=S.properties.find(p=>p.id===d.propertyId);await put('properties',{...p,rent:x.rent,statusId:'occupied',statusChangedAt:Date.now()})}})}
