function contractEditor(l={}){const base={propertyId:selected||S.properties[0]?.id||'',tenantName:'',rent:0,deposit:0,startDate:iso(),endDate:'',status:'Draft',terms:'ผู้ใช้ต้องตรวจทานและแก้ไขข้อสัญญาก่อนนำไปใช้จริง',...l};$('#contractEditor').classList.remove('empty');$('#contractEditor').innerHTML=`<div class="form-grid"><label class="field">ห้อง<select id="cProperty">${S.properties.map(p=>`<option value="${p.id}" ${p.id===base.propertyId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label class="field">ผู้เช่า<input id="cTenant" value="${esc(base.tenantName)}"></label><label class="field">เจ้าของ<input id="cOwner" value="${esc(base.ownerName)}"></label><label class="field">ค่าเช่า<input id="cRent" type="number" value="${base.rent}"></label><label class="field">เงินประกัน<input id="cDeposit" type="number" value="${base.deposit}"></label><label class="field">เริ่มสัญญา<input id="cStart" type="date" value="${base.startDate}"></label><label class="field">สิ้นสุดสัญญา<input id="cEnd" type="date" value="${base.endDate}"></label><label class="field full">เงื่อนไขเพิ่มเติม<textarea id="cTerms">${esc(base.terms)}</textarea></label></div><div id="contractPreview" class="contract-preview"></div><button class="secondary" id="printContract">พิมพ์ / บันทึก PDF</button> <button class="secondary" id="docxContract">Export DOCX</button> <button class="primary" id="saveContract">บันทึก Draft / Version</button>`;const read=()=>({id:base.id,propertyId:$('#cProperty').value,tenantName:$('#cTenant').value,ownerName:$('#cOwner').value,rent:+$('#cRent').value||0,deposit:+$('#cDeposit').value||0,startDate:$('#cStart').value,endDate:$('#cEnd').value,status:base.status,terms:$('#cTerms').value});const preview=()=>$('#contractPreview').textContent=contractText(read());$$('#contractEditor input,#contractEditor textarea,#contractEditor select').forEach(e=>e.oninput=preview);preview();$('#saveContract').onclick=async()=>{const x=read();if(!x.tenantName||!x.startDate||!x.endDate) return toast('กรอกผู้เช่าและวันที่สัญญาให้ครบ');if(x.endDate<x.startDate)return toast('วันสิ้นสุดไม่ถูกต้อง');const existing=x.id&&await get('leases',x.id),version=(await all('contractVersions')).filter(v=>v.leaseId===(x.id||'')).length+1;x.id=x.id||uid();await put('leases',x);await put('contractVersions',{id:uid(),leaseId:x.id,version,content:contractText(x),createdAt:Date.now()});toast('บันทึก Draft และ Version '+version+' แล้ว');await load()};$('#printContract').onclick=()=>{const w=window.open('','_blank');w.document.write(`<meta charset="utf-8"><title>สัญญาเช่า</title><pre style="font:16px system-ui;white-space:pre-wrap;line-height:2">${esc(contractText(read()))}</pre><script>print()<\/script>`);w.document.close()};$('#docxContract').onclick=()=>docx(contractText(read()),`สัญญาเช่า-${S.properties.find(p=>p.id===read().propertyId)?.name||'draft'}.docx`)}
function xml(s){return esc(s).replace(/\n/g,'</w:t></w:r></w:p><w:p><w:r><w:t xml:space="preserve">')}async function docx(text,name){if(!window.JSZip)return toast('กำลังโหลดตัวสร้าง DOCX โปรดลองใหม่');const z=new JSZip(),body=`<w:p><w:r><w:t xml:space="preserve">${xml(text)}</w:t></w:r></w:p>`;z.file('[Content_Types].xml','<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>');z.folder('_rels').file('.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>');z.folder('word').file('document.xml',`<?xml version="1.0" encoding="UTF-8"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>${body}<w:sectPr/></w:body></w:document>`);download(await z.generateAsync({type:'blob'}),name)}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function wireFiles(){$$('[data-photo]').forEach(b=>b.onclick=async()=>{const p=await get('photos',b.dataset.photo);$('#viewerBody').innerHTML=`<img src="${URL.createObjectURL(p.blob)}"><p>${esc(p.caption||'')}</p>`;$('#viewer').showModal()});$$('[data-cover]').forEach(b=>b.onclick=async()=>{const p=await get('photos',b.dataset.cover);for(const x of S.photos.filter(x=>x.propertyId===p.propertyId&&x.cover)){x.cover=false;await put('photos',x)}p.cover=true;await put('photos',p);await load()});$$('[data-delphoto]').forEach(b=>b.onclick=async()=>{await del('photos',b.dataset.delphoto);await load()});$$('[data-open]').forEach(b=>b.onclick=async()=>{const a=await get('attachments',b.dataset.open);window.open(URL.createObjectURL(a.blob),'_blank')});$$('[data-delatt]').forEach(b=>b.onclick=async()=>{await del('attachments',b.dataset.delatt);await load()})}
$('#photoFiles').onchange=async e=>{const pid=$('#photoPropertyFilter').value;if(!pid)return toast('เลือกห้องก่อนอัปโหลดรูป');const category=$('#photoCategoryFilter').value||'ภาพรวมของห้อง';for(const f of e.target.files)await put('photos',{id:uid(),propertyId:pid,name:f.name,blob:f,type:f.type,size:f.size,category,caption:'',date:iso(),cover:false,createdAt:Date.now()});e.target.value='';toast('เพิ่มรูปภาพแล้ว');await load()};
$('#attachmentFiles').onchange=async e=>{for(const f of e.target.files)await put('attachments',{id:uid(),name:f.name,blob:f,type:f.type,size:f.size,category:'เอกสาร',propertyId:selected||'',createdAt:Date.now()});e.target.value='';toast('เพิ่มเอกสารแล้ว');await load()};
$('#exportPhotos').onclick=async()=>{const pid=$('#photoPropertyFilter').value;if(!pid)return toast('เลือกห้องก่อน Export');if(!window.JSZip)return toast('กำลังโหลด JSZip โปรดลองใหม่');const ps=S.photos.filter(p=>p.propertyId===pid);if(!ps.length)return toast('ห้องนี้ยังไม่มีรูป');const z=new JSZip();ps.forEach(p=>z.file(p.name,p.blob));download(await z.generateAsync({type:'blob'}),`รูปภาพ-${S.properties.find(p=>p.id===pid).name}.zip`)};
function statusForm(s={}){modal(s.id?'แก้ไขสถานะ':'เพิ่มสถานะ',`<div class="form-grid"><label class="field">ชื่อสถานะ<input required name="name" value="${esc(s.name)}"></label><label class="field">สี<input type="color" name="color" value="${s.color||'#10a57a'}"></label><label class="field">ลำดับ<input type="number" name="sort" value="${s.sort??S.statuses.length}"></label><label class="field">การใช้งาน<select name="active"><option value="true" ${s.active!==false?'selected':''}>ใช้งาน</option><option value="false" ${s.active===false?'selected':''}>ปิดใช้งาน</option></select></label></div>`,async d=>{if(!d.name.trim())throw Error('ระบุชื่อสถานะ');await put('statuses',{...s,id:s.id||uid(),name:d.name.trim(),color:d.color,sort:+d.sort||0,active:d.active==='true'})})}
$('#addStatus').onclick=()=>statusForm();$('#statusList').onclick=e=>{const b=e.target.closest('[data-status]');if(b)statusForm(S.statuses.find(x=>x.id===b.dataset.status))};
async function backup(){if(!window.JSZip)return toast('กำลังโหลดตัวสร้าง Backup โปรดลองใหม่');const z=new JSZip(),data={format:'condo-ledger-full-backup',version:1,exportedAt:new Date().toISOString()};for(const s of ['properties','tenants','leases','contractVersions','statuses','statusHistory','settings'])data[s]=await all(s);for(const s of ['photos','attachments']){const records=await all(s);data[s]=records.map(({blob,...x})=>x);for(const r of records)z.file(`files/${s}/${r.id}`,r.blob)}z.file('backup.json',JSON.stringify(data));download(await z.generateAsync({type:'blob'}),`condo-ledger-full-backup-${iso()}.zip`)}
$('#backup').onclick=backup;$('#restoreFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!window.JSZip)return toast('กำลังโหลดตัวสร้าง Restore โปรดลองใหม่');try{const z=await JSZip.loadAsync(file),meta=JSON.parse(await z.file('backup.json').async('text'));if(meta.format!=='condo-ledger-full-backup')throw Error('ไฟล์ backup ไม่ถูกต้อง');for(const s of ['properties','tenants','leases','contractVersions','statuses','statusHistory','settings'])for(const x of meta[s]||[])await put(s,x);for(const s of ['photos','attachments'])for(const x of meta[s]||[]){const f=z.file(`files/${s}/${x.id}`);if(f)await put(s,{...x,blob:await f.async('blob')})}toast('Restore ข้อมูลและไฟล์แนบแล้ว');await load()}catch(x){toast('Restore ไม่สำเร็จ: '+x.message)}e.target.value=''};
$('#newContract').onclick=()=>contractEditor();$('#addHistoricContract').onclick=()=>leaseForm();$('#leaseSearch').oninput=renderArchive;$('#leasePropertyFilter').onchange=renderArchive;$('#photoPropertyFilter').onchange=renderGallery;$('#photoCategoryFilter').onchange=renderGallery;$$('.quick-property').forEach(b=>b.onclick=()=>propertyForm());$$('nav button,[data-page]').forEach(b=>b.onclick=()=>page(b.dataset.page));$('.mobile-menu').onclick=()=>$('aside').classList.toggle('open');$('#theme').onclick=()=>document.body.classList.toggle('dark');$('#closeViewer').onclick=()=>$('#viewer').close();load();
